    """
def convert_codewords(codewords: Any) -> object {
    list_of_strings = [];
    for lists in codewords {
        new_string = '';
        for item in lists {
            new_string = new_string + str(item);
        }
        list_of_strings.append(new_string);
    }
    return list_of_strings;
}

"""Pad or trim list to len length.

  Args:
    ids: list of ints to pad
    pad_id: what to pad with
    length: length to pad or trim to

  Returns:
    ids trimmed or padded with pad_id
  """
def Pad(ids: Any, pad_id: Any, length: Any) -> object {
    assert (pad_id is not None);
    assert (length is not None);
    if (len(ids) < length) {
        a = [pad_id] * (length - len(ids));
        return (ids + a);
    } else {
        return ids[:length];
    }
}

